INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_PROSDOCIMI_VENETIC','secondary scholarship','Aldo L. Prosdocimi, studies on the Venetic language and pantheon (Lingue e dialetti dell''Italia antica; ''Le religioni dell''Italia antica'')','Venetic theonyms, votive epigraphy, and cult of Reitia at Este/Lagole'),
 ('SRC_BEARD_ROMAN_RELIGIONS','secondary scholarship','Mary Beard, John North, Simon Price, Religions of Rome','Italic regional cult context and interpretatio Romana')
INSERT INTO _e VALUES
 ('ENT_VEN_PANTHEON','Venetic Pantheon','tradition_hub','tradition_hub','Venetic','pantheon-collective','B','Collective hub for the deities of the pre-Roman Veneti, attested through votive inscriptions at the sanctuaries of Este (Baratella) and Lagole di Calalzo.'),
 ('ENT_VEN_REITIA','Reitia','Healing goddess','Healing goddess','Venetic','healing; writing; underworld','B','Great Venetic goddess, principal deity of the Este (Baratella) sanctuary; goddess of healing, writing/literacy (votive alphabet tablets) and chthonic/underworld power. Best-attested Venetic theonym (dedications to ''Reitiai'').'),
 ('ENT_VEN_SAINAS','Sainas','Local deity','Local deity','Venetic','local cult; tutelary','C','Minor Venetic divine name known from votive epigraphy; cult function uncertain, plausibly a tutelary/healing-sphere deity associated with the Este/Lagole cult environment.'),
 ('ENT_VEN_TRUMUSIJATIS','Trumusijatis','Healing god','Healing god','Venetic','healing; thermal-spring cult','C','Venetic deity attested in dedications at the Lagole di Calalzo thermal-spring sanctuary (epithet/name ''Trumusijate-''); associated with the curative-waters cult.'),
 ('ENT_VEN_ATEGNATIS','Ategnatis','Local deity','Local deity','Venetic','local cult','C','Minor Venetic divine name (''Ate-'' / Ategnatis) recorded in votive inscriptions; function uncertain. HOMONYM CAUTION: unrelated to the Greek goddess Ate (ENT_ATE).'),
 ('ENT_VEN_PORA','Pora','Local goddess','Local goddess','Venetic','local cult; fertility/votive','C','Minor Venetic divine name appearing in votive epigraphy; goddess of uncertain function within the Venetic sanctuary cults.');
