INSERT INTO _p VALUES
 ('ENT_VEN_PANTHEON','PER_VENETIC','Collective hub for the deities of the pre-Roman Veneti, attested through votive inscriptions at the sanctuaries of Este (Baratella) and Lagole di Calalzo.'),
 ('ENT_VEN_REITIA','PER_VENETIC','Great Venetic goddess, principal deity of the Este (Baratella) sanctuary; goddess of healing, writing/literacy (votive alphabet tablets) and chthonic/underworld power. Best-attested Venetic theonym (dedications to ''Reitiai'').'),
 ('ENT_VEN_SAINAS','PER_VENETIC','Minor Venetic divine name known from votive epigraphy; cult function uncertain, plausibly a tutelary/healing-sphere deity associated with the Este/Lagole cult environment.'),
 ('ENT_VEN_TRUMUSIJATIS','PER_VENETIC','Venetic deity attested in dedications at the Lagole di Calalzo thermal-spring sanctuary (epithet/name ''Trumusijate-''); associated with the curative-waters cult.'),
 ('ENT_VEN_ATEGNATIS','PER_VENETIC','Minor Venetic divine name (''Ate-'' / Ategnatis) recorded in votive inscriptions; function uncertain. HOMONYM CAUTION: unrelated to the Greek goddess Ate (ENT_ATE).'),
 ('ENT_VEN_PORA','PER_VENETIC','Minor Venetic divine name appearing in votive epigraphy; goddess of uncertain function within the Venetic sanctuary cults.');
