INSERT INTO _r VALUES
 ('ENT_VEN_REITIA','member_of','ENT_VEN_PANTHEON','high','Reitia is the principal deity of the Venetic pantheon, head of the Este sanctuary cult.'),
 ('ENT_VEN_SAINAS','member_of','ENT_VEN_PANTHEON','medium','Sainas is a Venetic divine name attested within the Venetic votive-cult sphere.'),
 ('ENT_VEN_TRUMUSIJATIS','member_of','ENT_VEN_PANTHEON','medium','Trumusijatis is a Venetic deity of the Lagole sanctuary, part of the Venetic pantheon.'),
 ('ENT_VEN_ATEGNATIS','member_of','ENT_VEN_PANTHEON','medium','Ategnatis is a Venetic divine name belonging to the Venetic votive pantheon.'),
 ('ENT_VEN_PORA','member_of','ENT_VEN_PANTHEON','medium','Pora is a Venetic divine name belonging to the Venetic votive pantheon.'),
 ('ENT_VEN_REITIA','aligned_with','ENT_ARTEMIS','medium','Reitia''s healing and protective-of-women functions led to her functional identification with Greek Artemis in interpretatio.'),
 ('ENT_VEN_REITIA','aligned_with','ENT_ROM_DIANA','medium','Under Romanization the Este sanctuary cult of Reitia was assimilated toward Diana (Artemis'' Roman counterpart).'),
 ('ENT_VEN_REITIA','aligned_with','ENT_ROM_MINERVA','low','Reitia''s role as patron of writing/literacy (votive alphabet tablets) aligns her functionally with Minerva''s craft-and-learning sphere.'),
 ('ENT_VEN_TRUMUSIJATIS','aligned_with','ENT_VEN_REITIA','low','Trumusijatis shares the curative-cult sphere of the Venetic sanctuaries headed by Reitia, linking the thermal-spring healing deity to the great healing goddess.');
